-- 068 · Ajustes al documento del contrato TODO COSTO pedidos por Andrés el 21/10/2026.
-- 1) Plantilla todo costo v1.0: se elimina la figura "Director de Obra" (sin campo en Condiciones Particulares;
--    en cláusulas y anexos actúa directamente "el Contratante"; definiciones reletradas a) a f)). Se actualiza la
--    misma versión 1.0 porque ningún documento la usa todavía (la migración aborta si alguno la usa).
-- 2) Depósito privado contratos-anexos para adjuntar los documentos que hacen parte integral (Cláusula 3):
--    PDF, Excel o imagen hasta 20 MB. Leen admin y operativo; solo admin sube y solo si el contrato no está FIRMADO.
--    "Quitar" un adjunto solo lo saca de la lista (el archivo no se borra).
-- 3) anexos_integrales pasa a guardar objetos {nombre, path, archivo, tipo, tamano} (sigue aceptando textos).
-- No cambia datos existentes de obras.

do $do$
begin
  if exists (select 1 from contrato_documentos d join contrato_plantillas t on t.id = d.plantilla_id
             where t.plantilla = 'contrato_obra_contratista_tc' and t.version = '1.0') then
    raise exception 'La plantilla todo costo v1.0 ya está en uso: cree una versión nueva en vez de modificarla.';
  end if;
end $do$;

update public.contrato_plantillas
   set contenido = jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(contenido, '{condiciones_particulares,0,campos}', '[{"clave": "contratante_razon", "etiqueta": "Razón social", "origen": "fijo", "obligatorio": true, "tipo": "fijo", "valor_por_defecto": "HABITATUM S.A.S. – NIT 900.896.011-0"}, {"clave": "contratante_rep", "etiqueta": "Representante legal", "origen": "documento.campos (nombre y cédula)", "obligatorio": true, "tipo": "texto", "valor_por_defecto": "Arq. Andrés David Hincapié Cadavid"}, {"clave": "contratante_telefono_fijo", "etiqueta": "Teléfono", "origen": "fijo", "obligatorio": true, "tipo": "fijo", "valor_por_defecto": "321 748 4979"}, {"clave": "contratante_correo_fijo", "etiqueta": "Correo", "origen": "fijo", "obligatorio": true, "tipo": "fijo", "valor_por_defecto": "direcciondeproyectos@infohabitatum.com"}]'::jsonb), '{clausulas,0,parrafos}', '[{"tipo": "parrafo", "texto": "Para efectos del presente Contrato, los siguientes términos tendrán el significado que aquí se les asigna:"}, {"tipo": "literal", "texto": "a) Obra: el proyecto identificado en las Condiciones Particulares, que el Contratante ejecuta para el Propietario."}, {"tipo": "literal", "texto": "b) Propietario: el dueño del inmueble donde se ejecuta la Obra, con quien el Contratante tiene una relación independiente. No es parte de este Contrato."}, {"tipo": "literal", "texto": "c) Trabajos: las actividades, suministros e instalaciones objeto del Contrato, descritos en las Condiciones Particulares, el Anexo 1 (Cantidades y Precios) y el Anexo 2 (Condiciones Técnicas)."}, {"tipo": "literal", "texto": "d) Corte de Obra: medición conjunta, entre el Contratista y el Contratante, de los Trabajos ejecutados y recibidos a satisfacción en el periodo pactado, consignada en un acta que sirve de base para el pago."}, {"tipo": "literal", "texto": "e) Liberación: aprobación previa y escrita del Contratante, por bitácora, correo electrónico o mensaje escrito, antes de cubrir, vaciar u ocultar un trabajo."}, {"tipo": "literal", "texto": "f) Condiciones Particulares: el acápite II de este documento. En caso de contradicción prevalecen las Condiciones Particulares, luego las Condiciones Generales, luego el Anexo 2, luego el Anexo 1 y luego los documentos de la Cláusula 3."}]'::jsonb), '{clausulas,1,parrafos,0,texto}', '"El Contratista se obliga para con el Contratante a ejecutar, por su cuenta y riesgo, con plena autonomía técnica, administrativa y financiera, y con su propio personal y herramienta, los Trabajos descritos en las Condiciones Particulares y en los Anexos 1 y 2, conforme a los planos, especificaciones e instrucciones del Contratante. Como contraprestación, el Contratante pagará al Contratista el precio pactado."'::jsonb), '{clausulas,2,parrafos,0,texto}', '"Hacen parte integral de este Contrato, además de sus anexos, los documentos relacionados en las Condiciones Particulares, que el Contratista declara conocer y aceptar, en especial el pliego de condiciones con base en el cual presentó su oferta y el cuadro de cantidades y precios aprobados. En lo no regulado por este Contrato se aplicarán dichos documentos; en caso de contradicción, prevalece lo dispuesto en la Cláusula 1, literal f)."'::jsonb), '{clausulas,3,parrafos,2,texto}', '"Parágrafo. Si el Contratista advierte errores, omisiones o inconsistencias en planos o especificaciones, los informará por escrito al Contratante antes de ejecutar el trabajo afectado. Lo que ejecute sin consultar será corregido a su costo."'::jsonb), '{clausulas,4,parrafos,3,texto}', '"Parágrafo. Las obras no previstas en el Anexo 1 solo se ejecutarán y pagarán con aprobación escrita previa del Contratante, que fije su precio y su efecto en el plazo. Lo ejecutado sin dicha aprobación no será reconocido."'::jsonb), '{clausulas,5,parrafos,1,texto}', '"a) Al cierre de cada periodo, el Contratista y el Contratante medirán conjuntamente en la Obra las cantidades ejecutadas, y el Contratante elaborará el acta de Corte de Obra. Solo se pagan Trabajos terminados, medidos y recibidos a satisfacción."'::jsonb), '{clausulas,5,parrafos,2,texto}', '"b) Son requisitos para cada pago: (i) el acta de Corte de Obra firmada por el Contratante y el Contratista; y (ii) factura electrónica a nombre de HABITATUM S.A.S., con el IVA discriminado según el régimen pactado, o, si el Contratista no está obligado a facturar, cuenta de cobro a su nombre."'::jsonb), '{clausulas,8,parrafos,0,texto}', '"El plazo de ejecución es el señalado en las Condiciones Particulares. El Contratista se ajustará a la programación general de la Obra que defina el Contratante y se coordinará con los demás contratistas."'::jsonb), '{clausulas,8,parrafos,1,texto}', '"Las prórrogas solo procederán mediante otrosí escrito, solicitadas antes del vencimiento del plazo y por causas no imputables al Contratista, tales como obras no previstas aprobadas, suspensiones ordenadas por el Contratante o fuerza mayor debidamente acreditada."'::jsonb), '{clausulas,8,parrafos,2,texto}', '"Parágrafo. Si el Contratista presenta atrasos imputables a él, el Contratante podrá exigirle aumentar cuadrillas o frentes de trabajo, sin costo adicional, hasta recuperar el atraso."'::jsonb), '{clausulas,9,parrafos,2,texto}', '"b) Acatar únicamente las instrucciones del Contratante. Las solicitudes del Propietario, sus familiares o terceros se canalizarán a través del Contratante; el Contratista no ejecutará trabajos que este no le haya ordenado."'::jsonb), '{clausulas,9,parrafos,5,texto}', '"e) Cumplir el horario de trabajo establecido para la Obra, señalado en las Condiciones Particulares o el que fije por escrito el Contratante. Aunque el Contratista ejecuta los Trabajos a precio y con autonomía, y no por nómina, la presencia y las labores de su personal en la Obra se sujetarán a dicho horario y no a su libre criterio. Los trabajos por fuera de él requerirán autorización previa del Contratante."'::jsonb), '{clausulas,9,parrafos,6,texto}', '"f) Solicitar la Liberación del Contratante antes de cubrir, vaciar u ocultar cualquier trabajo."'::jsonb), '{clausulas,9,parrafos,8,texto}', '"h) Mantener el aseo diario de sus frentes y retirar sobrantes y escombros propios al sitio que indique el Contratante."'::jsonb), '{clausulas,10,parrafos,0,texto}', '"a) Materiales suministrados por el Contratante: el Contratista los solicitará por escrito al Contratante con una anticipación mínima de tres (3) días hábiles; recibirá y firmará las remisiones; responderá por su custodia, buen uso y pérdida desde su entrega; y devolverá los sobrantes. Las pérdidas y los materiales dañados por mal uso se descontarán a precio de reposición."'::jsonb), '{clausulas,11,parrafos,0,texto}', '"El Contratante podrá inspeccionar los Trabajos en cualquier momento y ordenar los ensayos que considere necesarios. Los Trabajos defectuosos o que no cumplan las especificaciones serán demolidos, retirados o rehechos por el Contratista, a su costo, dentro del plazo que le fije el Contratante. Si el Contratista no lo hace, el Contratante podrá ejecutarlos por medio de terceros y descontará su costo más un diez por ciento (10 %) de cualquier saldo a favor del Contratista. La aprobación de cortes o liberaciones no exonera al Contratista de su responsabilidad por defectos o vicios ocultos."'::jsonb), '{clausulas,13,parrafos,2,texto}', '"b) Reportar de inmediato al Contratante, y a la ARL dentro del término legal, todo accidente o incidente de trabajo."'::jsonb), '{clausulas,13,parrafos,3,texto}', '"Parágrafo. El Contratante podrá suspender actividades o exigir el retiro de trabajadores que incumplan las normas de seguridad, sin que ello genere prórroga del plazo ni costos adicionales."'::jsonb), '{clausulas,14,parrafos,1,texto}', '"a) Las pólizas deberán ser aprobadas por el Contratante y acompañarse del recibo de pago de la prima."'::jsonb), '{clausulas,16,parrafos,0,texto}', '"Terminados los Trabajos, el Contratante y el Contratista suscribirán el Acta de Recibo Final, con la lista de pendientes y el plazo para atenderlos; el recibo no implica renuncia a reclamar por vicios ocultos. Dentro de los treinta (30) días siguientes se suscribirá el Acta de Liquidación, con el valor final ejecutado, los pagos, los descuentos y los saldos, previa entrega del paz y salvo de su personal y de la póliza de estabilidad. Si el Contratista no la firma dentro de los diez (10) días hábiles siguientes a su envío, el Contrato podrá liquidarse unilateralmente."'::jsonb), '{clausulas,19,parrafos,0,texto}', '"El Contratante podrá suspender total o parcialmente los Trabajos por necesidades de la Obra, por incumplimiento de las normas de seguridad o por fuerza mayor, mediante acta, y el plazo se suspenderá por el mismo tiempo. Las suspensiones no generan pagos por tiempos muertos ni sobrecostos; si una no imputable al Contratista supera treinta (30) días, este podrá pedir la terminación con el pago de lo ejecutado."'::jsonb), '{clausulas,21,parrafos,0,texto}', '"El Contratista no podrá ceder el Contrato ni subcontratar total o parcialmente los Trabajos sin autorización previa y escrita del Contratante; aun autorizado, responderá solidariamente por sus subcontratistas."'::jsonb), '{clausulas,22,parrafos,1,texto}', '"a) No negociará con el Propietario precios, alcances, cambios ni trabajos adicionales en el inmueble, ni le presentará cotizaciones o cuentas de cobro; toda solicitud la remitirá al Contratante."'::jsonb), '{anexo_1,nota_B}', '"Solo se ejecutan y pagan con orden escrita previa del Contratante que fije la cantidad. Las horas se soportan con planilla diaria firmada por el Contratante. No suman al valor del contrato."'::jsonb), '{anexo_2,B_obligaciones_generales,2}', '"Solicitar la Liberación del Contratante antes de cubrir, vaciar u ocultar cualquier trabajo, y antes de iniciar cada frente que la requiera."'::jsonb), '{anexo_2,B_obligaciones_generales,3}', '"Presentar muestras o ejecutar un tramo de prueba cuando el Contratante lo solicite; el trabajo debe igualar la muestra aprobada."'::jsonb), '{anexo_2,B_obligaciones_generales,4}', '"Coordinar con los demás oficios los elementos embebidos, pases y remates. Prohibido romper, perforar o regatear elementos estructurales sin autorización escrita del Contratante."'::jsonb)
 where plantilla = 'contrato_obra_contratista_tc' and version = '1.0';

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('contratos-anexos', 'contratos-anexos', false, 20971520,
        array['application/pdf', 'image/jpeg', 'image/png',
              'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/vnd.ms-excel'])
on conflict (id) do nothing;

drop policy if exists contratos_anexos_lectura on storage.objects;
create policy contratos_anexos_lectura on storage.objects for select to authenticated
  using (bucket_id = 'contratos-anexos' and public.rol_actual() in ('admin', 'operativo'));

drop policy if exists contratos_anexos_subir on storage.objects;
create policy contratos_anexos_subir on storage.objects for insert to authenticated
  with check (bucket_id = 'contratos-anexos' and public.es_admin()
              and not exists (select 1 from public.contrato_documentos d
                              where d.contrato_id::text = (storage.foldername(name))[1] and d.estado = 'FIRMADO'));
